python3 -c "
import json
with open('/app/resources/treasury_bulletin_2017_06.json', 'r') as f:
    data = json.load(f)

# Look for OCS data in the structure
def find_ocs(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'outer' in k.lower() or 'continental' in k.lower() or 'shelf' in k.lower():
                print(f'{path}{k}: {v}')
            find_ocs(v, path + k + '.')
    elif isinstance(obj, list) and len(obj) > 0:
        find_ocs(obj[0], path + '[].')

find_ocs(data)
"
